const sph=(r,x,y,z,m,sx=1,sy=1,sz=1)=>{const e=add(new THREE.SphereGeometry(r,20,14),m,x,y,z);e.scale.set(sx,sy,sz);return e;};
const grp=(x,y,z,ry=0,fn)=>{const g=new THREE.Group();g.position.set(x,y,z);g.rotation.y=ry;const p=cur;p.add(g);cur=g;fn();cur=p;return g;};
